// Combines supabase/migrations/*.sql into supabase/setup.sql, for pasting into the
// Supabase SQL Editor on a fresh project. Run with: npm run db:setup-sql
import fs from 'node:fs'
import path from 'node:path'

const dir = 'supabase/migrations'
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort()
const parts = files.map((f) => `-- ===== ${dir}/${f} =====\n${fs.readFileSync(path.join(dir, f), 'utf8').trim()}\n`)
const header = [
  '-- MathConnect database setup. GENERATED by `npm run db:setup-sql`; edit the migrations, not this file.',
  '-- Run once on a fresh Supabase project: Dashboard → SQL Editor → New query → paste → Run.',
  '-- With the CLI, use `npx supabase db push` instead.',
].join('\n')

fs.writeFileSync('supabase/setup.sql', `${header}\n\n${parts.join('\n')}`)
console.log(`Wrote supabase/setup.sql from ${files.length} migration(s)`)
